import{_ as d,C as i,o,c as a,a2 as c,b as n,w as r,a as l,E as s,a3 as v}from"./chunks/framework.DZUUNQ77.js";const E=JSON.parse('{"title":"client/hook/providers · ContentProvider Hook","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/hook-providers.md","filePath":"reference/client/hook-providers.md","lastUpdated":1784494692000}'),P={name:"reference/client/hook-providers.md"};function p(h,e,k,u,C,m){const t=i("Mermaid");return o(),a("div",null,[e[1]||(e[1]=c('<h1 id="client-hook-providers-·-contentprovider-hook" tabindex="-1">client/hook/providers · ContentProvider Hook <a class="header-anchor" href="#client-hook-providers-·-contentprovider-hook" aria-label="Permalink to &quot;client/hook/providers · ContentProvider Hook&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/tree/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/hook/providers" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/hook/providers/</code></a></p></div><p>ContentProvider（CP）的 Hook 体系，共 7 个文件。CP 比系统服务复杂——它既涉及 <code>ContentResolver</code>，又涉及 <code>ActivityThread</code> 内部的 Provider 缓存。</p><h2 id="关键类" tabindex="-1">关键类 <a class="header-anchor" href="#关键类" aria-label="Permalink to &quot;关键类&quot;">​</a></h2><p>从源码提取的真实类清单：</p><table tabindex="0"><thead><tr><th>类</th><th>职责</th></tr></thead><tbody><tr><td><code>ProviderHook</code></td><td>CP Hook 基类，<code>implements InvocationHandler</code>，按 authority 静态分发到子类</td></tr><tr><td><code>SettingsProviderHook</code></td><td>代理 Settings Provider，<code>Settings.Secure.ANDROID_ID</code> 返回伪造值</td></tr><tr><td><code>DownloadProviderHook</code></td><td>代理 Downloads Provider</td></tr><tr><td><code>MediaProviderHook</code></td><td>代理 Media Provider</td></tr><tr><td><code>InternalProviderHook</code></td><td>内部（虚拟环境内）Provider 代理</td></tr><tr><td><code>ExternalProviderHook</code></td><td>外部（系统）Provider 代理</td></tr><tr><td><code>QueryRedirectCursor</code></td><td>包装 <code>Cursor</code>，重定向查询结果（IO 重定向在 CP 层的延伸）</td></tr></tbody></table><p><code>ProviderHook</code> 的 <code>PROVIDER_MAP</code> 按 authority（<code>settings</code>/<code>downloads</code>/<code>media</code>）注册 <code>HookFetcher</code>，命中时构造对应子类代理。<code>external</code> 标志区分该 Provider 是走虚拟环境内还是真实系统。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><p>详见 <a href="./../../features/ipc-bridge">IPC 桥</a> 的 <code>StubCP</code> 部分。要点：</p><ul><li><code>VClientImpl.fixInstalledProviders</code> 修复 <code>ActivityThread</code> 的 Provider 缓存</li><li><code>clearSettingProvider</code> 清掉系统 Settings Provider 缓存</li><li><code>ProviderHook</code> 代理 Settings Provider，让 <code>Settings.Secure.ANDROID_ID</code> 返回伪造值（见 <a href="./../../features/device-spoofing">设备信息伪造</a>）</li><li>跨进程 CP 调用通过 <code>ProviderCall</code>（无需 Context）</li></ul>',10)),(o(),n(v,null,{default:r(()=>[s(t,{id:"mermaid-118",class:"mermaid",graph:"flowchart%20LR%0A%20%20APP%5B%22%E7%9B%AE%E6%A0%87%20App%3Cbr%2F%3ESettings.Secure.getString%22%5D%20--%3E%20AR%5B%22ActivityThread%20Provider%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20AR%20--%3E%20PH%5B%22ProviderHook%20%E4%BB%A3%E7%90%86%22%5D%0A%20%20PH%20--%3E%20FAKE%5B%22%E8%BF%94%E5%9B%9E%E4%BC%AA%E9%80%A0%20androidId%22%5D%0A%20%20APP%20--%3E%7C%22ContentResolver.call%22%7C%20PC%5B%22ProviderCall%3Cbr%2F%3E(%E8%B7%A8%E8%BF%9B%E7%A8%8B)%22%5D%0A%20%20PC%20--%3E%20SRV%5B%22server%20%E6%88%96%E7%B3%BB%E7%BB%9F%20Provider%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1}))])}const _=d(P,[["render",p]]);export{E as __pageData,_ as default};
